            JSONObject status=w.call("workbench_status",a(),sc);check(status.optBoolean("ok")&&status.getInt("uid")==android.os.Process.myUid()&&status.getInt("worker_pid")!=android.os.Process.myPid()&&status.getJSONObject("browser_zoom").optBoolean("pinch")&&status.optBoolean("scheduled_live_watch"),"built-in worker unavailable: "+status);report(reports,"same_app_separate_process");
            w.call("workbench_file",a("action","mkdir","path",dir),sc);JSONObject file=w.call("workbench_file",a("action","write","path",dir+"/hello.txt","text","hello workbench"),sc);check(file.optString("sha256").length()==64&&w.call("workbench_file",a("action","read","path",dir+"/hello.txt"),sc).getString("text").equals("hello workbench"),"file roundtrip");report(reports,"file_write_read_hash");
            check(!w.call("workbench_file",a("action","stat","path","../../escape"),sc).optBoolean("ok"),"path escape accepted");report(reports,"file_path_boundary");
            JSONObject good=job(w,a("command","printf 'pear\\napple\\npear\\n' | sort -u > sorted.txt; cat sorted.txt; echo stderr-check >&2","cwd",dir),sc);check(good.getInt("exit_code")==0&&good.getString("stdout").equals("apple\npear\n")&&good.getString("stderr").contains("stderr-check"),"real pipeline: "+good);report(reports,"real_sh_pipeline_stdout_stderr");
            JSONObject bad=job(w,a("command","echo expected-failure >&2; exit 7"),sc);check(bad.getInt("exit_code")==7&&bad.getString("stderr").contains("expected-failure"),"exit code swallowed");report(reports,"nonzero_shell_exit");
            check(status.optString("shell_security").contains("same app UID"),"shell authority hidden");report(reports,"same_uid_boundary_reported");
            JSONObject input=w.call("terminal_start",a("command","read word; printf 'received:%s' \"$word\""),sc);w.call("terminal_input",a("job_id",input.getString("job_id"),"text","stdin-ok\n").put("close_stdin",true),sc);check(await(w,input,sc).getString("stdout").equals("received:stdin-ok"),"stdin failed");report(reports,"real_stdin_and_eof");
            JSONObject timeout=job(w,a("command","sleep 4; echo should-not-run").put("timeout_ms",200),sc);check("timed_out".equals(timeout.optString("state"))&&!timeout.optString("stdout").contains("should-not-run"),"timeout failed: "+timeout);report(reports,"timeout_process_group");
            JSONObject stop=w.call("terminal_start",a("command","sleep 4; echo should-not-run"),sc);Thread.sleep(100);w.call("terminal_stop",a("job_id",stop.getString("job_id")),sc);check("cancelled".equals(await(w,stop,sc).optString("state")),"cancel failed");report(reports,"cancel_process_group");
            JSONObject cascade=w.call("terminal_start",a("command","sleep 4; echo should-not-run"),sc);Thread.sleep(100);JSONObject cascadeResult=w.cancelTask(t.getString("id"),t.getString("conversation"));check(cascadeResult.optBoolean("ok")&&"cancelled".equals(await(w,cascade,sc).optString("state")),"task-level terminal cancellation failed");report(reports,"task_level_cancel_stops_terminal_job");
            check(!w.call("terminal_status",a("job_id",good.getString("job_id")),new JSONObject().put("task_id","other-task")).optBoolean("ok"),"foreign task read job");report(reports,"terminal_task_ownership");
            JSONObject http=w.call("http_request",a("url",f.url("/echo"),"method","POST","body","payload-workbench","output_file",dir+"/api.json").put("headers",a("X-Test","header-workbench")),sc);check(http.optBoolean("ok")&&http.getInt("status")==200&&new JSONObject(http.getString("text")).getString("body").equals("payload-workbench")&&http.getJSONObject("file").optBoolean("exists"),"HTTP POST/save: "+http);report(reports,"http_method_headers_body_file");
            JSONObject patch=w.call("http_request",a("url",f.url("/echo"),"method","PATCH","body","patch-body"),sc);check(patch.optBoolean("ok")&&new JSONObject(patch.getString("text")).getString("method").equals("PATCH"),"HTTP PATCH: "+patch);report(reports,"http_patch");
            JSONObject redirect=w.call("http_request",a("url",f.url("/redirect")).put("headers",a("Authorization","fixture-token","Cookie","fixture-cookie")),sc);JSONObject echo=new JSONObject(redirect.getString("text"));check(redirect.getJSONArray("redirects").length()==1&&echo.isNull("authorization")&&echo.isNull("cookie"),"redirect leaked credentials: "+redirect);report(reports,"cross_origin_redirect_credentials");
            JSONObject missing=w.call("http_request",a("url",f.url("/missing")),sc);check(!missing.optBoolean("ok")&&missing.getInt("status")==404&&missing.getString("text").contains("fixture_missing"),"404 evidence lost");report(reports,"http_error_response_evidence");
            JSONObject large=w.call("http_request",a("url",f.url("/large")).put("max_bytes",1000),sc);check(large.optBoolean("truncated")&&large.getInt("bytes")==1000,"HTTP size limit");check(!w.call("http_request",a("url",f.url("/large"),"output_file",dir+"/partial.txt").put("max_bytes",1000),sc).optBoolean("ok"),"partial download falsely saved");report(reports,"http_bounded_body_no_partial_file");
            check(!w.call("http_request",a("url","file:///data/local/tmp/x"),sc).optBoolean("ok"),"HTTP accepted file URL");check(!w.call("http_request",a("url",f.url("/slow")).put("timeout_ms",1000),sc).optBoolean("ok"),"HTTP ignored deadline");report(reports,"http_scheme_and_deadline");
            w.showBrowser();Thread.sleep(600);JSONObject page=w.call("browser_open",a("url",f.url("/page")).put("new_tab",true),sc);check(page.optBoolean("ok")&&!page.optBoolean("loading"),"browser open: "+page);String tab=page.getString("tab_id");JSONObject snap=w.call("browser_snapshot",a("tab_id",tab),sc),dom=snap.getJSONObject("dom");check(dom.getString("text").contains("Workbench ready"),"DOM missing");report(reports,"browser_navigation_and_dom");
            String inputRef="",buttonRef="";JSONArray elements=dom.getJSONArray("elements");for(int i=0;i<elements.length();i++){JSONObject e=elements.getJSONObject(i);if(e.getString("tag").equals("input"))inputRef=e.getString("ref");if(e.optString("text").equals("Apply"))buttonRef=e.getString("ref");}
            JSONObject act=a("tab_id",tab,"page_id",snap.getString("page_id"),"snapshot_id",dom.getString("snapshot_id"));check(w.call("browser_action",new JSONObject(act.toString()).put("action","type").put("ref",inputRef).put("text","AI-value"),sc).optBoolean("ok"),"DOM type");check(w.call("browser_action",new JSONObject(act.toString()).put("action","click").put("ref",buttonRef),sc).optBoolean("ok"),"DOM click");check(w.call("browser_snapshot",a("tab_id",tab),sc).getJSONObject("dom").getString("text").contains("Saved AI-value"),"DOM result");report(reports,"browser_dom_type_click_result");
            JSONObject zoomed=w.call("browser_action",a("tab_id",tab,"page_id",snap.getString("page_id"),"action","zoom_out"),sc),fitted=w.call("browser_action",a("tab_id",tab,"page_id",snap.getString("page_id"),"action","fit"),sc);check(zoomed.optBoolean("ok")&&zoomed.optInt("zoom_percent")>=10&&zoomed.optInt("zoom_percent")<=100&&fitted.optBoolean("ok")&&fitted.optInt("zoom_percent")>=10&&fitted.optInt("zoom_percent")<=100,"browser zoom baseline or fit reset failed: "+zoomed+" / "+fitted);report(reports,"browser_zoom_and_fit_controls");
            JSONObject js=w.call("browser_eval",a("tab_id",tab,"page_id",snap.getString("page_id"),"script","Promise.resolve({answer:42,native:typeof window.OPhoneAINative,bridge:typeof window.OPhoneAI})"),sc);check(js.optBoolean("ok")&&js.getJSONObject("value").getInt("answer")==42&&js.getJSONObject("value").getString("native").equals("undefined")&&js.getJSONObject("value").getString("bridge").equals("undefined"),"JS/native boundary: "+js);report(reports,"async_js_without_native_bridge");
            JSONObject fetched=w.call("browser_eval",a("tab_id",tab,"page_id",snap.getString("page_id"),"script","fetch('/stream.m3u8').then(r=>r.text()).then(t=>t.length)"),sc);check(fetched.optBoolean("ok")&&fetched.optInt("value")>20,"fixture media fetch failed");JSONObject media=w.call("browser_media",a("tab_id",tab,"page_id",snap.getString("page_id")),sc);check(media.optBoolean("ok")&&media.getJSONArray("media").length()>0&&!media.toString().contains("EXT-X"),"browser media discovery failed: "+media);String mediaId=media.getJSONArray("media").getJSONObject(0).getString("media_id");JSONObject stream=w.call("stream_record_start",a("tab_id",tab,"media_id",mediaId,"duration_seconds","5","output_name","fixture.ts").put("_test_no_publish",true),sc);for(int i=0;i<100&&stream.optLong("finished_at")==0;i++){Thread.sleep(50);stream=w.call("stream_record_status",a("stream_id",stream.getString("stream_id")),sc);}check("completed".equals(stream.optString("state"))&&stream.optLong("bytes")>=2800&&stream.optString("sha256").length()==64&&stream.optString("media_uri").isEmpty(),"direct HLS stream recording failed: "+stream);job(w,a("command","rm -f "+new File(stream.getString("artifact_path")).getName(),"cwd","recordings"),sc);report(reports,"browser_media_private_id_and_direct_hls_recording");
            JSONObject watcher=w.call("stream_record_watch_start",a("tab_id",tab,"duration_seconds","5","deadline_epoch_ms",String.valueOf(System.currentTimeMillis()+30000),"output_name","watch-fixture.ts").put("_test_no_publish",true),sc);check(java.util.Arrays.asList("scheduled","waiting_for_live").contains(watcher.optString("state")),"live watcher did not enter wait state: "+watcher);w.call("browser_eval",a("tab_id",tab,"page_id",snap.getString("page_id"),"script","fetch('/stream.m3u8').then(r=>r.text())"),sc);for(int i=0;i<160&&watcher.optLong("finished_at")==0;i++){Thread.sleep(50);watcher=w.call("stream_record_status",a("stream_id",watcher.getString("stream_id")),sc);}check("completed".equals(watcher.optString("state"))&&watcher.optLong("bytes")>=2800,"event live watcher failed: "+watcher);job(w,a("command","rm -f "+new File(watcher.getString("artifact_path")).getName(),"cwd","recordings"),sc);report(reports,"scheduled_live_watch_detects_media_and_records_once");
            check(!w.call("browser_action",act.put("action","click").put("ref",buttonRef),sc).optBoolean("ok"),"stale snapshot accepted");w.call("browser_open",a("tab_id",tab,"url",f.url("/page?next")),sc);check(!w.call("browser_action",act.put("action","scroll"),sc).optBoolean("ok"),"stale page accepted");report(reports,"stale_dom_and_page_rejection");
            check(!w.call("browser_open",a("url","file:///data/local/tmp/x"),sc).optBoolean("ok"),"browser accepted file URL");JSONObject image=w.call("browser_screenshot",a("tab_id",tab),sc);check(image.optString("image_base64").length()>1000||image.optString("error").contains("show_browser_before_screenshot"),"unexpected screenshot failure: "+image);report(reports,image.optBoolean("ok")?"browser_scheme_and_image":"browser_scheme_and_unshown_image_rejection");
            JSONObject task=new JSONObject(t.toString());JSONArray criteria=new JSONArray().put(a("kind","browser_page","tab_id",tab,"url",f.url("/page?next"),"text_contains","Workbench ready")).put(a("kind","terminal_job","job_id",good.getString("job_id"))).put(a("kind","workbench_file","path",dir+"/sorted.txt"));task.put("criteria",criteria);check(TaskVerifier.verify(c,task).optBoolean("verified"),"workbench native verification: "+TaskVerifier.verify(c,task));criteria.getJSONObject(0).put("url",f.url("/wrong"));check(!TaskVerifier.verify(c,task).optBoolean("verified"),"wrong page falsely verified");criteria.getJSONObject(0).put("url",f.url("/page?next"));criteria.getJSONObject(1).put("job_id",bad.getString("job_id"));check(!TaskVerifier.verify(c,task).optBoolean("verified"),"nonzero exit falsely verified");report(reports,"fresh_page_file_job_verification");
